document.addEventListener("DOMContentLoaded",function(){var t=location.host.replace("www.","");t=new RegExp(t,"i");for(var e=document.getElementsByTagName("a"),n=0;n<e.length;n++){var a=e[n].host;t.test(a)||e[n].setAttribute("target","_blank")}}),$(function(){"use strict";var t={prefetch:!0,cacheLength:10,scroll:!0,onStart:{duration:500,render:function(t){t.addClass("is-exiting"),e.restartCSSAnimations()}},onReady:{duration:0,render:function(t,e){t.removeClass("is-exiting"),t.html(e),e.find(".off").removeClass("off")}}},e=$("#maincontainer").smoothState(t).data("smoothState")});